-- Check interactions for engage_activity_pivot FI133051
SELECT i.activity_reg, i.time_mark, i.interact_fan_pivot, i.interact_idol_pivot, i.chat_activity->>'Msg_Tone' as tone
FROM interactions i
WHERE i.activity_reg IN (
    SELECT e.engage_activity_pivot FROM engagement WHERE e.engage_activity_pivot = 'FI133051'
);

-- Check all FK paths involving socialcommunity
SELECT * FROM information_schema.table_constraints 
WHERE table_name = 'socialcommunity' AND constraint_type = 'FOREIGN KEY';

SELECT i.interact_fan_pivot, i.chat_activity->>'Msg_Tone' as tone
FROM interactions i
WHERE i.interact_idol_pivot = 'VI5706';

SELECT COUNT(*) FROM socialcommunity sc
JOIN engagement e ON sc.social_engage_pivot = e.engage_reg
JOIN retentionandinfluence ri ON e.engage_reg = ri.retain_engage_pivot;
